using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    [Fact]
    public async Task The_request_sent_to_the_provider_has_the_expected_shape()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Authorize("ORD-7", new Money(12.50m, "eur"));

        var seen = Assert.Single(provider.Requests);
        Assert.Equal("POST", seen.Method);
        Assert.Equal("/v1/authorizations", seen.Path);
        Assert.StartsWith("application/json", seen.ContentType);
        using var json = JsonDocument.Parse(seen.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_required_refusal_is_read_as_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_approved(string body)
    {
        provider.Respond(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task A_rejected_request_or_provider_failure_surfaces_as_an_error(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_an_error()
    {
        provider.Respond(200, "<html>not json</html>");
        await Assert.ThrowsAsync<JsonException>(() => Authorize());
    }

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-1", Money? amount = null)
    {
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var gateway = new HttpPaymentGateway(client);
        return gateway.AuthorizeAsync(reference, amount ?? new Money(10m, "EUR"), CancellationToken.None);
    }

    public void Dispose() => provider.Dispose();

    private sealed record SeenRequest(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<SeenRequest> requests = [];
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            // Retry on the rare chance the chosen port is taken before the listener binds.
            for (var attempt = 0; ; attempt++)
            {
                var port = new Random().Next(20000, 60000);
                var prefix = $"http://127.0.0.1:{port}/";
                var candidate = new HttpListener();
                candidate.Prefixes.Add(prefix);
                try
                {
                    candidate.Start();
                    listener = candidate;
                    BaseAddress = new Uri(prefix);
                    break;
                }
                catch (HttpListenerException) when (attempt < 10) { candidate.Close(); }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; }

        public IReadOnlyList<SeenRequest> Requests { get { lock (requests) return [.. requests]; } }

        public void Respond(int statusCode, string responseBody) => (status, body) = (statusCode, responseBody);

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var requestBody = await reader.ReadToEndAsync();
                lock (requests)
                    requests.Add(new(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, requestBody));

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
